pragma solidity ^0.8.36;
contract AssemblyFlow {
    struct S { bool f; }
    S private s;
    function conditional(bool flag) internal view {
        S storage value;
        assembly { if flag { value.slot := s.slot } }
        value;
    }
    function missingDefault(uint256 selector) internal view {
        S storage value;
        assembly { switch selector case 0 { value.slot := s.slot } }
        value;
    }
    function completeSwitch(bool selector) internal view {
        S storage value;
        assembly { switch selector case 0 { value.slot := s.slot } default { value.slot := s.slot } }
        value;
    }
    function readBeforeAssignment() internal view {
        S storage value;
        assembly { pop(value.slot) value.slot := s.slot }
    }
    function terminal(uint256 y) public pure returns (uint256 x) {
        assembly { revert(0, 0) x := y }
    }
    function transactionReturn(uint256 y) public pure returns (uint256 x) {
        assembly { return(0, 0) }
        x = y;
    }
    function loopBreak() public pure {
        assembly {
            for { let a := 0 } lt(a, 1) { a := add(a, 1) } {
                break
