            }
        }
    }
}
abstract contract VirtualBase {
    function always() internal pure virtual {}
    function inherited(bool flag) external pure returns (uint256) {
        if (flag) return 1;
        always();
    }
}
contract VirtualDerived is VirtualBase {
    function always() internal pure override { revert(); }
}
contract ModifierBase {
    modifier guarded() virtual { revert(); _; }
    function inherited() internal guarded returns (uint256) { uint256 local; local; }
}
contract ModifierDerived is ModifierBase {
    modifier guarded() override { _; }
    function expose() external { inherited(); }
}
